// Brooklyn: inner-right position, tilted (Figma 1722:30077 — 269.7×258.8 @ 29.26°)
const BK_X = 888, BK_Y = 314, BK_W = 270, BK_H = 259
const BK_PIN_CX = BK_X + BK_W / 2
const BK_PIN_CY = BK_Y + BK_H / 2
const BK_ROT = 29.26

// Vietnam: far-right position, tilted (Figma 1722:29992 — 263.8×551.3 @ 11.05°)
const VN_X = 1087, VN_Y = 177, VN_W = 264, VN_H = 551
const VN_PIN_CX = VN_X + VN_W / 2
const VN_PIN_CY = VN_Y + VN_H / 2
const VN_ROT = 11.05

// Pin anchors in SVG coords (Figma 1722:29993 / 1722:30078)
const VN_LABEL = { x: 1117, y: 140 }
const BK_LABEL = { x: 929, y: 283 }

// "Places I call home!" label position in SVG coords (Figma 1722:30090)
const HOME_LABEL = { x: 880, y: 64 }

const VIEWBOX_W = 1440, VIEWBOX_H = 900

function svgToScreen(svgX: number, svgY: number, vw: number, vh: number) {
  const scale = Math.max(vw / VIEWBOX_W, vh / VIEWBOX_H)
  const offsetX = (vw - VIEWBOX_W * scale) / 2
  const offsetY = (vh - VIEWBOX_H * scale) / 2
  return { x: svgX * scale + offsetX, y: svgY * scale + offsetY }
}

// Exact Figma pin icon SVG — dark mode colors (home page is always dark)
function PinIcon() {
  return (
    <svg width="24" height="29" viewBox="0 0 24 28.9844" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ flexShrink: 0 }}>
      <path d="M21 10C21 17 12 23 12 23C12 23 3 17 3 10C3 7.61305 3.94821 5.32387 5.63604 3.63604C7.32387 1.94821 9.61305 1 12 1C14.3869 1 16.6761 1.94821 18.364 3.63604C20.0518 5.32387 21 7.61305 21 10Z" stroke="#8ca7c2" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
      <path d="M12 13C13.6569 13 15 11.6569 15 10C15 8.34315 13.6569 7 12 7C10.3431 7 9 8.34315 9 10C9 11.6569 10.3431 13 12 13Z" stroke="#8ca7c2" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
      <ellipse cx="12" cy="26.9922" rx="5.24609" ry="1.99219" fill="rgba(140,167,194,0.3)"/>
    </svg>
  )
}

function MapPin({ city, time }: { city: string; time: string }) {
  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      gap: 4,
      pointerEvents: 'none',
    }}>
      <PinIcon />
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <span style={{
          fontFamily: "'Neue Montreal', sans-serif",
          fontSize: 16,
          fontWeight: 400,
          color: '#e6e9ed',
          whiteSpace: 'nowrap',
          lineHeight: 1,
        }}>
          {city}
        </span>
        <span style={{
          fontFamily: "'Neue Montreal', sans-serif",
          fontSize: 16,
          fontWeight: 400,
          color: '#899aaa',
          whiteSpace: 'nowrap',
          lineHeight: 1,
        }}>
          {time}
        </span>
      </div>
    </div>
  )
}

function fmt(tz: string) {
  return new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(new Date()).toLowerCase()
}

export default function MapHotspots({ visible }: { visible: boolean }) {
  const [hovered, setHovered] = useState<'brooklyn' | 'vietnam' | null>(null)
  const [viewport, setViewport] = useState({ w: 0, h: 0 })
  const [times, setTimes] = useState({ vn: '', ny: '' })

  useEffect(() => {
    const update = () => setViewport({ w: window.innerWidth, h: window.innerHeight })
    update()
    window.addEventListener('resize', update)
    return () => window.removeEventListener('resize', update)
  }, [])

  useEffect(() => {
    const tick = () => setTimes({ vn: fmt('Asia/Ho_Chi_Minh'), ny: fmt('America/New_York') })
    tick()
    const id = setInterval(tick, 1000)
    return () => clearInterval(id)
  }, [])

  if (!visible) return null

  const svgProps = {
    viewBox: '0 0 1440 900',
    preserveAspectRatio: 'xMidYMid slice' as const,
    style: { width: '100%', height: '100%', position: 'absolute' as const, inset: 0 },
    fill: 'none' as const,
  }

  const { w, h } = viewport
  const vnScreen = w ? svgToScreen(VN_LABEL.x, VN_LABEL.y, w, h) : null
  const bkScreen = w ? svgToScreen(BK_LABEL.x, BK_LABEL.y, w, h) : null
  const homeScreen = w > 760 ? svgToScreen(HOME_LABEL.x, HOME_LABEL.y, w, h) : null

  return (
    <>
      {/* Layer 1: map shapes — below ID card */}
      <div className="map-shapes-layer" style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 5 }}>
        <svg {...svgProps}>
          {/* Brooklyn — inner-right position, tilted */}
          <g
            transform={`rotate(${BK_ROT} ${BK_PIN_CX} ${BK_PIN_CY})`}
            onMouseEnter={() => setHovered('brooklyn')}
            onMouseLeave={() => setHovered(null)}
            style={{ pointerEvents: 'all', cursor: 'default' }}
          >
            <g transform={`translate(${BK_X}, ${BK_Y}) scale(${BK_W / 325}, ${BK_H / 295})`}>
              <path d={BROOKLYN_D} fill="transparent" stroke="none" />
              <path
                d={BROOKLYN_D}
                fill={hovered === 'brooklyn' ? 'rgba(255,255,255,0.08)' : 'none'}
                style={{ transition: 'fill 0.25s ease', pointerEvents: 'none' }}
              />
              <path
                d={BROOKLYN_D}
                fill="none"
                stroke="rgba(255,255,255,0.5)"
                strokeDasharray="16 16"
                vectorEffect="non-scaling-stroke"
                style={{ pointerEvents: 'none' }}
              />
            </g>
          </g>

          {/* Vietnam — far-right position, tilted */}
          <g
            transform={`rotate(${VN_ROT} ${VN_PIN_CX} ${VN_PIN_CY})`}
            onMouseEnter={() => setHovered('vietnam')}
            onMouseLeave={() => setHovered(null)}
            style={{ pointerEvents: 'all', cursor: 'default' }}
          >
            <g transform={`translate(${VN_X}, ${VN_Y}) scale(${VN_W / 376}, ${VN_H / 551})`}>
              <path fillRule="evenodd" clipRule="evenodd" d={VIETNAM_D} fill="transparent" stroke="none" />
              <path
                fillRule="evenodd" clipRule="evenodd"
                d={VIETNAM_D}
                fill={hovered === 'vietnam' ? 'rgba(255,255,255,0.08)' : 'none'}
                style={{ transition: 'fill 0.25s ease', pointerEvents: 'none' }}
              />
              <path
                fillRule="evenodd" clipRule="evenodd"
                d={VIETNAM_D}
                fill="none"
                stroke="rgba(255,255,255,0.5)"
                strokeDasharray="16 16"
                vectorEffect="non-scaling-stroke"
                style={{ pointerEvents: 'none' }}
              />
            </g>
          </g>
        </svg>
      </div>

      {/* "Places I call home!" — appears only while a map shape is hovered */}
      {hovered && homeScreen && (
        <p style={{
          position: 'absolute',
          left: homeScreen.x,
          top: homeScreen.y,
          margin: 0,
          fontFamily: "'Neue Montreal', sans-serif",
          fontSize: 24,
          fontWeight: 400,
          letterSpacing: 0.48,
          color: '#939393',
          whiteSpace: 'nowrap',
          zIndex: 5,
          pointerEvents: 'none',
        }}>
          Places I call home!
        </p>
      )}

      {/* Layer 2: HTML pins — above ID card, hover only */}
      {hovered === 'vietnam' && vnScreen && (
        <div style={{
          position: 'absolute',
          left: vnScreen.x,
          top: vnScreen.y - 16,
          zIndex: 15,
          pointerEvents: 'none',
        }}>
          <MapPin city="Buôn Ma Thuột, Việt Nam" time={times.vn} />
        </div>
      )}
      {hovered === 'brooklyn' && bkScreen && (
        <div style={{
          position: 'absolute',
          left: bkScreen.x,
          top: bkScreen.y - 16,
          zIndex: 15,
          pointerEvents: 'none',
        }}>
          <MapPin city="Brooklyn, NY" time={times.ny} />
        </div>
      )}
    </>
  )
}
